#!/usr/bin/env bash
#
# A QA wizard walks a developer through every acceptance criterion of one
# feature, one stage at a time: open the page, do the steps, record pass or fail.
# Generated by /speckit.qa.walk from extensions/qa/scripts/qa-wizard.sh.
# Adapted from Matt Pocock's `wizard` skill (github.com/mattpocock/skills), MIT.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-check stages below the marker.
#
# Usage: ./qa-walk.sh [--only US1-2,EC-1] [--no-browser] [--reopen] [--results <path>]
#   --only       walk only these stage ids; other rows in the results file are kept
#   --no-browser print each URL instead of opening it
#   --reopen     open every URL again, even one already opened this run
#   --results    where the markdown results table goes (default: beside this script)

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

ONLY=""
NO_BROWSER="${NO_BROWSER:-}"
REOPEN=""
RESULTS=""

while [[ $# -gt 0 ]]; do
  case "$1" in
    # A bare --only eats the next option as its value, so the filter matches no
    # stage and the walk reports success having checked nothing.
    --only)
      [[ $# -ge 2 && "$2" != --* ]] ||
        { printf '%s\n' '--only needs a stage list' >&2; exit 2; }
      ONLY="$2"; shift 2 ;;
    --only=*)     ONLY="${1#*=}"; shift ;;
    --no-browser) NO_BROWSER=1; shift ;;
    --reopen)     REOPEN=1; shift ;;
    --results)
      [[ $# -ge 2 && "$2" != --* ]] ||
        { printf '%s\n' '--results needs a path' >&2; exit 2; }
      RESULTS="$2"; shift 2 ;;
    --results=*)  RESULTS="${1#*=}"; shift ;;
    -h|--help)    sed -n '11,15p' "${BASH_SOURCE[0]}"; exit 0 ;;
    *) printf 'unknown option: %s\n' "$1" >&2; exit 2 ;;
  esac
done

# The last entry of BASH_SOURCE is the wizard itself, whether this library was
# copied into it or sourced from beside it, so the results land by the wizard.
_WIZARD="${BASH_SOURCE[$((${#BASH_SOURCE[@]} - 1))]}"
RESULTS="${RESULTS:-$(cd "$(dirname "$_WIZARD")" && pwd)/qa-walk-results.md}"

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
_STAGE_ID=""
_SKIPPING=""      # non-empty while --only excludes the current stage
RECORDS=()        # one tab-separated record per check: id, check, result, note
_SEEN=()          # every stage id this wizard declares, for the --only check
_OPENED=()        # every URL opened this run, so none is opened twice

# _clear wipes the terminal so only the current stage is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# _excluded ID succeeds when --only was given and does not name ID.
_excluded() {
  [[ -n "$ONLY" ]] || return 1
  [[ ",$ONLY," != *",$1,"* ]]
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser. This wizard tells you what to open and what to look\n' "$DIM"
  printf '  for, then records pass, fail or skip for each check. Stop any time with\n'
  printf '  Ctrl-C. Re-run with --only <id,...> to walk only the stages you name.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage ID "Title" clears the screen, announces the stage and shows progress.
# The id is the spec's own (US1-2, EC-1, SC-003) so results trace back to it.
stage() {
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  _STAGE_ID="$1"
  _SEEN+=("$1")
  if _excluded "$1"; then _SKIPPING=1; return 0; fi
  _SKIPPING=""
  _clear
  printf '\n%s%s▸ Stage %s/%s · %s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$2" "$RESET"
}

# say "..." prints the Given: the state the check starts from.
say()  { [[ -n "$_SKIPPING" ]] || printf '  %s\n' "$1"; }
# step "..." is one action the developer takes: the When.
step() { [[ -n "$_SKIPPING" ]] || printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { [[ -n "$_SKIPPING" ]] || printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { [[ -n "$_SKIPPING" ]] || printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }
good() { [[ -n "$_SKIPPING" ]] || printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

# open_url URL opens it in the developer's browser, cross-platform incl. WSL.
open_url() {
  [[ -n "$_SKIPPING" ]] && return 0
  local url="$1"
  if [[ -n "$NO_BROWSER" ]]; then
    printf '  %s↗ open%s %s\n' "$GREEN" "$RESET" "$url"; return 0
  fi
  # A walk returns to the same page many times: one wizard opens 5 pages across
  # 35 calls. Opening each time buries the reviewer in duplicate tabs, so a URL
  # already opened this run is named instead. --reopen restores every open.
  if [[ -z "$REOPEN" ]]; then
    local opened=" ${_OPENED[*]-} "
    if [[ "$opened" == *" $url "* ]]; then
      printf '  %s↗ already open%s %s\n' "$DIM" "$RESET" "$url"
      return 0
    fi
  fi
  _OPENED+=("$url")
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview      >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open     >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open         >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the developer to finish the manual part.
pause() {
  [[ -n "$_SKIPPING" ]] && return 0
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes. Put it before any
# step that changes data.
confirm() {
  [[ -n "$_SKIPPING" ]] && return 1
  local reply=""
  printf '  %s? %s [y/N]%s ' "$YELLOW" "$1" "$RESET"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# check "expected" states the Then and records pass, fail or skip for the
# current stage. A fail or a skip takes a one-line note.
check() {
  [[ -n "$_SKIPPING" ]] && return 0
  printf '  %s✔ Expected:%s %s\n' "$BOLD" "$RESET" "$1"
  local verdict="" reply="" note_text="" colour=""
  while [[ -z "$verdict" ]]; do
    printf '  %s? pass / fail / skip [p/f/s]%s ' "$YELLOW" "$RESET"
    # End of input records a skip, so a piped run never spins.
    if ! read -r reply; then verdict="skip"; break; fi
    case "${reply//[[:space:]]/}" in
      [pP]*) verdict="pass" ;;
      [fF]*) verdict="fail" ;;
      [sS]*) verdict="skip" ;;
    esac
  done
  if [[ "$verdict" != "pass" ]]; then
    printf '  %sNote (what you saw, or why skipped):%s ' "$BOLD" "$RESET"
    read -r note_text || true
  fi
  case "$verdict" in
    pass) colour="$GREEN" ;;
    fail) colour="$RED" ;;
    *)    colour="$YELLOW" ;;
  esac
  printf '  %s%s%s\n' "$colour" "$verdict" "$RESET"
  RECORDS+=("$(printf '%s\t%s\t%s\t%s' "$_STAGE_ID" "$1" "$verdict" "$note_text")")
}

# finish clears, writes the results table and shows the closing summary. On an
# --only run, rows for stages not walked this time are kept from the previous
# file. Exit code is 1 when any check failed.
finish() {
  local rows=() line id record r_id r_check r_result r_note
  local pass=0 fail=0 skip=0

  # An id that names no stage silently filters every stage out, and the walk
  # then reports success having checked nothing. Refuse before the results file
  # is written, so a mistyped id never overwrites the rows of a good run.
  if [[ -n "$ONLY" ]]; then
    # Join under the default IFS, because ${_SEEN[*]} separates on the first
    # character of IFS and the split below needs IFS to be a comma.
    local seen=" ${_SEEN[*]-} "
    local -a missing=()
    local want
    local IFS=,
    for want in $ONLY; do
      [[ "$seen" == *" $want "* ]] || missing+=("$want")
    done
    unset IFS
    if [[ ${#missing[@]} -gt 0 ]]; then
      printf '%s\n' "no stage in this wizard is named: ${missing[*]}" >&2
      exit 2
    fi
  fi

  if [[ -n "$ONLY" && -f "$RESULTS" ]]; then
    while IFS= read -r line; do
      [[ "$line" == '| '* ]] || continue
      id="${line#| }"; id="${id%% |*}"
      [[ "$id" == "Id" || "$id" == "---" ]] && continue
      _excluded "$id" && rows+=("$line")
    done < "$RESULTS"
  fi

  for record in ${RECORDS[@]+"${RECORDS[@]}"}; do
    IFS=$'\t' read -r r_id r_check r_result r_note <<< "$record"
    rows+=("| $r_id | ${r_check//|/\\|} | $r_result | ${r_note//|/\\|} |")
  done

  for line in ${rows[@]+"${rows[@]}"}; do
    case "$line" in
      *"| pass |"*) pass=$((pass + 1)) ;;
      *"| fail |"*) fail=$((fail + 1)) ;;
      *"| skip |"*) skip=$((skip + 1)) ;;
    esac
  done

  {
    printf '# QA walk results\n\n'
    printf -- '- **Run**: %s\n' "$(date '+%Y-%m-%d %H:%M')"
    printf -- '- **Result**: %s pass, %s fail, %s skip\n\n' "$pass" "$fail" "$skip"
    printf '| Id | Check | Result | Note |\n|---|---|---|---|\n'
    for line in ${rows[@]+"${rows[@]}"}; do printf '%s\n' "$line"; done
  } > "$RESULTS"

  _clear
  printf '\n'
  if [[ "$fail" -gt 0 ]]; then
    printf '%s%s  ✗ %s check(s) failed%s\n' "$BOLD" "$RED" "$fail" "$RESET"
  else
    printf '%s%s  ✓ Walk complete%s\n' "$BOLD" "$GREEN" "$RESET"
  fi
  printf '%s  %s pass, %s fail, %s skip · written to %s%s\n' \
    "$DIM" "$pass" "$fail" "$skip" "$RESULTS" "$RESET"
  for record in ${RECORDS[@]+"${RECORDS[@]}"}; do
    IFS=$'\t' read -r r_id r_check r_result r_note <<< "$record"
    [[ "$r_result" == "pass" ]] && continue
    printf '  %s- %s %s: %s%s\n' "$DIM" "$r_id" "$r_result" "$r_note" "$RESET"
  done
  printf '\n'
  [[ "$fail" -gt 0 ]] && exit 1
  return 0
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage per check, in the confirmed order.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=27

BASE_URL="https://localhost:58671"
HOME_URL="$BASE_URL/"
RECIPES_URL="$BASE_URL/recipes/"
EMPTY_SEARCH_URL="$BASE_URL/recipes/?q=zzzznomatch"
DETAIL_URL="$BASE_URL/recipes/spicy-ramen-flight/"
NO_VARIANTS_URL="$BASE_URL/recipes/bare-cupboard-snack-board/"
VARIANT_URL="$BASE_URL/recipes/fluffy-buttermilk-pancakes/classic-stack"
LOGIN_URL="$BASE_URL/account/login"
REGISTER_URL="$BASE_URL/register"
REGISTRATION_COMPLETE_URL="$BASE_URL/account/registration-complete"
ACCOUNT_URL="$BASE_URL/account"
SETTINGS_URL="$BASE_URL/account/settings"
CREATE_RECIPE_URL="$BASE_URL/recipes/create-recipe"
NOT_FOUND_URL="$BASE_URL/no-such-page-for-qa"

NOTE_BUILD="Run this after implement, on a site built with yarn build:all, with the Development seeder run (curl -sk -X POST $BASE_URL/api/dev/seed-recipes). Mockups to compare with: specs/002-paper-piles-not-tape/mockups/pile-light.jpg and pile-dark.jpg."
NOTE_BLANK="A blank sheet is the plain torn paper under a sheet: no ruling, no content, a different torn edge, centred, turned about 1.5 degrees off the top sheet (0.5 degrees on a wide sheet: the hero, the pad's page and any sheet wider than 700px)."
NOTE_RAMP="Switch the ramp when a stage says so. Signed in, the account settings page saves Light or Dark. Signed out, set prefers-color-scheme to dark in your browser's rendering tools, then reload."
NOTE_INSPECT="To count blanks exactly, run this in the console: document.querySelectorAll('main .kcc-blank').length, and compare it with document.querySelectorAll('main .kcc-slip').length. The two counts match, apart from a slip that is a stacker or pad part named in the stage."

banner "QA walk: Paper Piles, Not Tape"

stage "US1-1" "Recipe search grid: every card on one blank sheet"
note "$NOTE_BUILD"
note "$NOTE_BLANK"
say "Given the recipe search grid with its first page of results."
open_url "$RECIPES_URL"
step "Wait for the grid. Look at three cards in different rows."
step "Each card has one blank sheet showing around its edge, with a torn edge and a tilt of its own, different from the card's."
step "Look along the grid in reading order: neighbouring blank sheets turn in opposite directions."
step "Open the filters (on a phone width, tap the filters control first) and look again: the blanks still alternate."
check "Each recipe card shows one blank sheet under it, with a different torn edge and a different tilt from the card."

stage "US4-1" "A card lifts and its blank sheet stays put"
say "Given the recipe search grid in a desktop-width window."
open_url "$RECIPES_URL"
step "Hover over a recipe card. The card, with its icon tile, rises a few pixels."
step "Watch the blank sheet under it: it does not move."
step "Move the pointer away, then press Tab until the keyboard focus enters a card. The card lifts the same way and its blank sheet stays still."
note "The browser pane does not set :hover. Use a real browser window for the hover half."
check "The card lifts and the sheet under it stays where it was."

stage "US4-3" "Reduced motion: nothing moves"
say "Given the recipe search grid with reduced motion switched on."
open_url "$RECIPES_URL"
step "Turn on reduced motion: macOS System Settings, Accessibility, Display, Reduce motion, or emulate prefers-reduced-motion: reduce in the browser's rendering tools. Reload the page."
step "Hover over a card, then focus one with the keyboard."
step "Neither the card nor its blank sheet moves."
note "Turn reduced motion off again after this stage."
check "Nothing moves."

stage "EC-1" "A card that grows to its row: the blank grows with it"
say "Given a grid row where one card is taller than its neighbours (a long recipe name or a long description)."
open_url "$RECIPES_URL"
step "Find a row where cards differ in natural height, or narrow the window until a long name wraps to more lines."
step "Compare each card's blank sheet with its card, in the same row."
check "The sheet under it grows with it, so the pile never shows a short under-sheet."

stage "EC-2" "The blank's torn edge differs from the card's and from its neighbours"
say "Given the recipe search grid."
open_url "$RECIPES_URL"
step "Pick a card and compare the shape of its torn edge with the torn edge of the blank sheet showing around it."
step "Compare the card with the card beside it."
check "Neighbouring sheets in a grid already avoid sharing a torn edge. The sheet under a card also avoids the card's own edge."

stage "US1-2" "Recipe detail: the hero and each sheet on a blank"
note "$NOTE_BLANK"
say "Given a recipe with variants."
open_url "$DETAIL_URL"
step "Look at the hero at the top, then scroll down through each sheet: the At a glance sheets, the variant cards and the rest."
step "The hero shows one blank sheet under it, turned about 0.5 degrees, with a torn edge unlike the hero's. Every sheet below it shows one blank too."
step "Look at the hero's top centre."
check "The hero and each sheet below it show one blank sheet under them, and the hero has no strip of tape at its top centre."

stage "US2-2" "Featured card and hero: only the tile's strip of tape"
say "Given a recipe with a featured variant."
open_url "$DETAIL_URL"
step "Look at the featured recipe card and the hero. Each has a small strip of tape holding its icon tile."
step "Look at the top centre of both sheets: there is no second strip."
check "Only the tile's strip remains."

stage "US2-1" "Icon tiles keep their strip of tape"
say "Given a recipe card, the featured recipe card and a detail hero."
open_url "$RECIPES_URL"
step "Look at the icon tile on a recipe card in the grid: it has its small strip of tape."
step "Switch to list view if the page offers it: each row's icon tile has a strip of tape too."
open_url "$DETAIL_URL"
step "Look at the featured card and the hero: each icon tile has its strip of tape."
check "Its icon tile keeps its strip of tape."

stage "US2-3" "The kit offers no way to tape a sheet"
say "Given an author who builds a new sheet."
open_url "$BASE_URL/recipes/"
step "In the repository, open docs/brand/kit.md and search it for tape. Tape is documented only for items applied on top of a sheet (inside a tile wrapper)."
step "Open src/KCC.Web/Features/Components/Sheet/KccSheet.vue: it has no tape prop."
step "Run: grep -rn kcc-tape src/KCC.Web/Features --include=*.vue --include=*.cshtml. Every hit sits inside a kcc-tilewrap."
check "The kit offers none. Tape exists only for items applied on top of a sheet."

stage "US1-3" "Empty state, success message and small hero: no tape, one blank"
note "$NOTE_BLANK"
say "Given sheets that used to take tape."
open_url "$EMPTY_SEARCH_URL"
step "The search finds nothing and shows the empty state: no tape on it, one blank sheet under it."
open_url "$NO_VARIANTS_URL"
step "This recipe has no variants. Its empty state has no tape and sits on one blank sheet."
open_url "$HOME_URL"
step "Find a small hero on the home page, if the home page carries one. It has no tape and one blank sheet."
step "The success message is the 'Recipe Submitted!' sheet at the end of the recipe wizard (Create Recipe, fill the form, submit). Check it the same way when you walk the wizard, or mark this stage on the first three."
check "It has no tape and shows one blank sheet under it."

stage "EC-3" "Clipped or scrolling sheets still show their blank, and no page scrolls sideways"
say "Given a phone-width window (375px wide) and a tall sheet."
open_url "$RECIPES_URL"
step "Narrow the window to 375px, or use the browser's phone emulation."
step "Open the recipe filters so the sheet is tall. Its blank sheet still shows along the sides."
step "Try to scroll the page sideways. It does not move. Repeat on a recipe's detail page and a variant page."
open_url "$VARIANT_URL"
step "Look at the ingredients sheet beside a long instructions sheet: the blank is no taller than its sheet."
check "A sheet that scrolls horizontally, or that is clipped by its container, still shows its under-sheet."

stage "US1-5" "Crisp sheets: the top stays square, the blank keeps its turn"
say "Given a crisp sheet, such as the sign-in form or the Create Recipe form."
open_url "$LOGIN_URL"
step "Look at the sign-in sheet: its edges are square, not tilted."
step "Look at the blank sheet showing under it: it keeps a small tilt."
open_url "$CREATE_RECIPE_URL"
step "The Create Recipe sheet (sign in if the site asks) shows the same: square top, tilted blank."
check "The top sheet stays square and the sheet under it keeps a small tilt."

stage "EC-4" "Full-screen sheets: cook mode and the photo viewer"
say "Given the variant page, signed in."
open_url "$VARIANT_URL"
step "Choose Cook mode. The overlay opens. Look at its sheet: one blank sheet under it, showing along any edge the screen does not cut off."
step "Close it. In the recipe wizard's photo step (Create Recipe, From photos, add a photo), open a photo in the viewer and look for the same under-sheet."
check "A full-screen sheet, such as the photo viewer or cook mode, still shows the under-sheet along any edge that the screen does not cut off."

stage "EC-5" "The pad's menu cards get no under-sheet"
say "Given any page, desktop width."
open_url "$HOME_URL"
step "Open the Recipes menu in the header pad. The menu card slides out. It has no blank sheet of its own."
step "Open the My Kitchen menu and look at its card the same way."
check "The pad's menu cards are already in the pile. They get no under-sheet of their own."

stage "US3-1" "The header pad: one page under the top sheet"
say "Given any page."
open_url "$HOME_URL"
step "Look at the header pad: the top sheet, and one blank page under it, centred."
step "Count the pages showing under the top sheet. There was three before."
check "One blank page shows under the pad's top sheet, where three show today."

stage "US3-2" "Menus slide out from between the two sheets"
say "Given the header pad."
open_url "$HOME_URL"
step "Open the Recipes menu. The card slides out from between the top sheet and the page under it, and fans out from its far corner."
step "Close it, then open My Kitchen. It does the same."
check "The menu card slides out from between the top sheet and the page under it, and fans out from its far corner as it does today."

stage "US3-3" "The pad tucks away and returns with its one page"
say "Given a long page."
open_url "$RECIPES_URL"
step "Scroll down until the pad tucks away."
step "Scroll up. The pad returns."
step "At no point does a page show alone, without its top sheet."
check "The pad returns with its one page under it, and no page shows alone."

stage "EC-6" "Icon tiles get tape and no blank sheet"
say "Given a recipe card."
open_url "$RECIPES_URL"
step "Look at an icon tile on a card: it has its strip of tape."
step "Look around the tile for a blank sheet of its own: there is none."
check "An icon tile is applied on top of a sheet. It gets tape and no under-sheet."

stage "EC-7" "Label pills get neither tape nor a blank sheet"
say "Given a page with label pills (the recipe search filters, a card's difficulty or time label)."
open_url "$RECIPES_URL"
step "Look at the label pills on cards and in the filters."
step "None has a strip of tape. None has a blank sheet under it."
check "A label pill is printed on the sheet. It gets neither tape nor an under-sheet."

stage "US1-4" "Razor pages follow the same rule"
say "Given pages the server renders without Vue."
open_url "$REGISTRATION_COMPLETE_URL"
step "Look at the registration complete sheet: one blank sheet under it, no tape."
open_url "$NOT_FOUND_URL"
step "The 404 page: its sheet has one blank sheet under it, no tape."
note "The registration complete page may redirect when you are signed in. Sign out, or register a test member at $REGISTER_URL, if it does."
check "Its sheet follows the same rule as a Vue sheet."

stage "US4-2" "A stacked sheet steps back with its blank"
say "Given a home page with a stacker block."
open_url "$HOME_URL"
step "Scroll slowly through the stacker: the next sheet slides up and covers the one before."
step "Watch the covered sheet: its blank sheet steps back with it, so the pile stays together."
check "The sheet under it steps back with it, so the pile stays together."

stage "US1-6" "Dark ramp: the blank reads as paper on the dark desk"
note "$NOTE_RAMP"
say "Given the dark ramp."
open_url "$RECIPES_URL"
step "Switch to the dark ramp and reload. Look at the grid: each blank sheet reads as paper on the dark desk, and is neither lost in the desk nor glowing."
open_url "$DETAIL_URL"
step "Look at the hero, the sheets below it and the header pad."
open_url "$REGISTRATION_COMPLETE_URL"
step "Look at the Razor sheet."
step "Compare with specs/002-paper-piles-not-tape/mockups/pile-dark.jpg and with the light ramp."
check "The sheet under each sheet reads as paper on the dark desk, as it does in the light ramp."

stage "EC-8" "A ramp switch: the pile switches with its sheet"
note "$NOTE_RAMP"
say "Given any page with several sheets."
open_url "$RECIPES_URL"
step "Switch the ramp, in either direction. Motion freezes for one frame."
step "Look at every blank sheet right after the switch: each is in the new ramp, none keeps the old ramp's colour."
check "A ramp switch freezes motion for one frame. The pile switches ramp with its sheet."

stage "SC-001" "Every sheet has exactly one blank sheet, none has tape"
note "$NOTE_INSPECT"
say "Given every public page type."
open_url "$HOME_URL"
step "Check Home, the recipe search, a recipe detail page, a variant page, the account page, account settings, the sign-in page, the registration complete page and a 404."
step "On each page run the console check from the note, and look for any sheet with a strip of tape of its own."
check "On every public page type, every sheet has exactly one blank sheet under it, and none of them has tape."

stage "SC-002" "Tape appears on icon tiles only"
say "Given every public page type."
open_url "$RECIPES_URL"
step "On the recipe search, a recipe detail page and a variant page, find every strip of tape."
step "In the console, run document.querySelectorAll('.kcc-tape').length and confirm each one sits in a tile wrapper (its parent has the kcc-tilewrap class)."
check "Every icon tile keeps its strip of tape, and tape appears nowhere else."

stage "SC-003" "The pad shows one page, and both menus open between the two sheets"
say "Given any page."
open_url "$HOME_URL"
step "Count the pages under the pad's top sheet: one."
step "Open the Recipes menu, then My Kitchen. Each card comes out between the top sheet and the page under it."
check "The header pad shows exactly one page under its top sheet, and both menus open between the two sheets."

stage "SC-004" "Hover or focus: the card lifts and its blank does not move"
say "Given the recipe search grid in a desktop-width window."
open_url "$RECIPES_URL"
step "Hover over several cards one after the other, then Tab through a row of them."
step "On each one the card lifts, and the blank sheet under it stays where it was."
check "On a hover or a focus, a recipe card lifts and its blank sheet does not move."

finish
